function getWordtuneTranslation(key, lang) {
  if (wordtuneTranslations[lang] && wordtuneTranslations[lang][key]) {
    return wordtuneTranslations[lang][key];
  }
  if (wordtuneTranslations.en && wordtuneTranslations.en[key]) {
    return wordtuneTranslations.en[key];
  }
  return null;
}

function applyWordtuneTranslations(lang) {
  console.log(`🔥 Applying wordtune translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.wordtune.') || key.startsWith('review.common.'))) {
      const translation = getWordtuneTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} wordtune translations`);
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyWordtuneTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyWordtuneTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyWordtuneTranslations(currentLang);
}

console.log('✅ wordtune i18n loaded');
